(function(){'use strict';const P=DecideCatalogParty,el=id=>document.getElementById(id),panel=document.createElement('article');panel.id='catalogPartyPanel';panel.innerHTML='<h2>เพื่อนร่วมทีมจากฐานข้อมูล</h2><p>รับเฉพาะ NPC ที่เปิด recruitable • ใช้ค่าสถานะ อุปกรณ์ และวิชาที่เชื่อมแล้วจากฐานข้อมูล • รวมผู้เล่นสูงสุด 8 คน</p><p id="catalogPartySummary"></p><button id="catalogPartyOpen">จัดเพื่อนร่วมทีม</button>';el('gameScreen').prepend(panel);const box=document.createElement('dialog');box.id='catalogPartyDialog';box.innerHTML='<h2>จัดเพื่อนร่วมทีม</h2><div id="catalogPartyRoster"></div><label>NPC ที่รับได้<select id="catalogPartyChoice"></select></label><button id="catalogPartyRecruit">รับเข้าทีม</button><button id="catalogPartyRest">พักฟื้นเพื่อนทั้งหมด · 8 ชั่วโมง</button><p id="catalogPartyStatus" role="status"></p><button id="catalogPartyClose">ปิด</button>';document.body.append(box);let message='';const rows=()=>R.records(DB);
function run(fn){try{s=fn();save();render();message='บันทึกปาร์ตี้แล้ว';draw();}catch(e){message=e.message;draw();}}
function draw(){if(!s.character)return;const roster=P.validate(s.catalogParty),library=rows();el('catalogPartySummary').textContent='เพื่อน '+roster.length+'/'+P.capacity(s)+' คน • พร้อมรบ '+roster.filter(p=>p.hp>0).length+' คน';const root=el('catalogPartyRoster');root.replaceChildren();for(const p of roster){const npc=library.find(r=>r.kind==='npc'&&r.id===p.id),line=document.createElement('p');line.textContent=(npc?.displayName||npc?.name||p.id)+' • HP '+p.hp+' • MP '+p.mp+' ';const button=document.createElement('button');button.textContent='ให้ออกจากทีม';button.dataset.dismissNpc=p.id;button.disabled=!!s.expedition||DecideWorldLinks.busy(s);button.onclick=()=>run(()=>P.dismiss(s,p.id));line.append(button);root.append(line);}const select=el('catalogPartyChoice'),prior=select.value;select.replaceChildren();for(const r of library.filter(r=>r.kind==='npc'&&r.enabled!==false&&r.recruitable===true&&DecideWorldLinks.npcAllowed(s,r.id,DB.overrides?.[EvervaleMapData.KEY])&&!roster.some(p=>p.id===r.id)))select.add(new Option(r.displayName||r.name,r.id));if([...select.options].some(o=>o.value===prior))select.value=prior;el('catalogPartyRecruit').disabled=!select.options.length||roster.length>=P.capacity(s)||!!s.expedition||DecideWorldLinks.busy(s);el('catalogPartyRest').disabled=!roster.length||!!s.expedition||DecideWorldLinks.busy(s);el('catalogPartyStatus').textContent=message;}
el('catalogPartyOpen').onclick=()=>{message='';draw();box.showModal();};el('catalogPartyClose').onclick=()=>box.close();el('catalogPartyRecruit').onclick=()=>run(()=>P.recruit(s,rows(),el('catalogPartyChoice').value));el('catalogPartyRest').onclick=()=>run(()=>{const next=P.rest(s,rows());R.clock(next,480);return next;});window.addEventListener('evervale-save',draw);new MutationObserver(()=>{if(!el('gameScreen').hidden)draw();}).observe(el('gameScreen'),{attributes:true,attributeFilter:['hidden']});window.DecideCatalogPartyUI={draw};
})();
